p_runnext:

			; Main.bas 142: Dim n As Integer, t As Integer, r As Integer, c As Integer

			; Main.bas 143: fr = Not fr
			dw kw_notv, var_fr, var_fr

			; Main.bas 144: If fr Then
			dw kw_goto_ifzero_n, var_fr, if17_1

