			; Main.bas 178: n = n + 1
			dw kw_inc, var_runnext_n

			; Main.bas 179: If c < 13 Or c > 35 Or n >= 32 Or st(t) <> 2 Then Exit Do
			dw kw_scpltvl, var_runnext_c, 13
